{
  "name": "TCP数据采样进程",
  "name_en": "TCP Sampler Process",
  "manufacturer": "",
  "description": "一个非物理的软件采样组件，用于在实验数据采集链路中通过 TCP 接收数据包、提取有用报文内容、缓存原始数据，并可选择将数据写入磁盘。它更像是面向测试或数据传输基准比较的进程式采样工具，而不是直接控制某台实体仪器。",
  "description_en": "A non-physical software sampling component used in laboratory data-acquisition pipelines to receive packets over TCP, extract useful packet content, buffer raw data, and optionally record data to disk. It appears to be a process-based sampler intended for testing or TCP/UDP transfer benchmarking rather than direct control of a physical instrument.",
  "actions": [
    {
      "action_name": "auto-init_new_process",
      "description": "初始化新的采样子进程及其运行资源。",
      "description_en": "Initialize a new sampler subprocess and its runtime resources."
    },
    {
      "action_name": "auto-createConnection",
      "description": "建立到指定地址的 TCP 连接。",
      "description_en": "Establish a TCP connection to the specified address."
    },
    {
      "action_name": "auto-get_useful_packets",
      "description": "从接收到的数据包中提取有用的报文或报头内容。",
      "description_en": "Extract useful packet or header content from a received packet."
    },
    {
      "action_name": "auto-enable",
      "description": "获取或设置数据处理循环的启用状态。",
      "description_en": "Get or set the enabled state of the processing loop."
    },
    {
      "action_name": "auto-record",
      "description": "获取或设置是否将原始数据记录到磁盘。",
      "description_en": "Get or set whether raw data recording to disk is enabled."
    },
    {
      "action_name": "auto-close_file",
      "description": "获取或设置关闭当前输出文件的状态。",
      "description_en": "Get or set the state for closing the current output file."
    },
    {
      "action_name": "auto-outfile_name",
      "description": "获取或设置输出文件名。",
      "description_en": "Get or set the output file name."
    },
    {
      "action_name": "auto-pre_run",
      "description": "在主运行循环开始前执行准备操作。",
      "description_en": "Perform setup steps before the main run loop starts."
    },
    {
      "action_name": "auto-post_run",
      "description": "在主运行循环结束后执行收尾处理。",
      "description_en": "Perform cleanup steps after the main run loop ends."
    },
    {
      "action_name": "auto-run",
      "description": "运行主 TCP 采样循环，接收、解析、缓存并转发原始数据。",
      "description_en": "Run the main TCP sampling loop to receive, parse, buffer, and forward raw data."
    },
    {
      "action_name": "auto-stopRaw2Disk",
      "description": "停止原始数据写盘流程。",
      "description_en": "Stop the raw-data-to-disk writing process."
    }
  ],
  "tag_hints": [
    "TCP packet reception",
    "data acquisition pipeline",
    "raw data buffering",
    "disk recording",
    "process-based sampler",
    "network benchmarking"
  ]
}

